mapper.select:
select l.poi_id as poiId, p.name as poiName, l.member_id as memberId,
       l.coupon_id as couponId, l.status as status, l.trigger_lat as triggerLat,
       l.trigger_lng as triggerLng, l.create_time as createTime,
       p.city_code as cityCode, p.merchant_id as merchantId
from roam_poi_reward_log l left join roam_poi p on p.id = l.poi_id

   and l.poi_id = #{poiId}
   and l.member_id = #{memberId}
   and l.status = #{status}

order by l.create_time desc
limit 500

select , (select n.avatar from npc_profile n where n.scope_type = 2 and n.scope_id = p.merchant_id and n.enabled = 1 and n.audit_status = 1 and n.del_flag = '0' order by n.sort asc, n.id asc limit 1) as npc_avatar,
(exists (select 1 from roam_poi_found f where f.poi_id = p.id and f.member_id = #{memberId}) or exists (select 1 from roam_poi_reward_log r where r.poi_id = p.id and r.member_id = #{memberId} and r.status in (0, 1))) as found,
(exists (select 1 from roam_poi_reward_log r where r.poi_id = p.id and r.member_id = #{memberId} and r.status = 0 and r.coupon_id > 0)) as pending_redeem from roam_poi p where p.status = 1 and and p.lat between #{minLat} and #{maxLat} and p.lng between #{minLng} and #{maxLng}
order by power(p.lat - (#{minLat} + #{maxLat}) / 2, 2) + power((p.lng - (#{minLng} + #{maxLng}) / 2) * cos(radians((#{minLat} + #{maxLat}) / 2)), 2) asc, p.id asc limit #{limit}

select  from roam_poi
where status = 1 and id in
#{id}

select p.* from roam_poi_found f
join roam_poi p on p.id = f.poi_id
where f.session_id = #{sessionId}

select * from roam_session where member_id = #{memberId}

    and id = #{sessionId}
    and client_session_key = #{clientSessionKey}

select id, member_id, started_at, finished_at, distance_m, tiles_revealed, pois_found, xp_awarded,
       recall_sent_at, recall_attempts, recall_last_attempt_at, status, create_time
from roam_session where id = #{id}

mapper.update:
update roam_session set presence_visible = #{visible}
where member_id = #{memberId} and status = 0
and id = #{id}

mapper.select:
select t.memberId, t.nickname, t.avatar, t.lat, t.lng, t.explorePct, t.shops, t.elapsedSec
from (
    select s.member_id as memberId, m.nickname as nickname, m.avatar as avatar,
           s.last_lat as lat, s.last_lng as lng, s.explore_pct as explorePct,
           (select count(distinct v.source_type, v.source_id)
              from roam_shop_visit v where v.session_id = s.id) as shops,
           timestampdiff(second, coalesce(s.started_at, s.create_time, #{now}), #{now}) as elapsedSec,
           row_number() over (partition by s.member_id order by s.last_report_at desc, s.id desc) as rn
    from roam_session s join ums_member m on m.id = s.member_id
    where s.member_id <> #{memberId}
      and s.status = 0 and s.presence_visible = 1
      and s.last_report_at is not null and s.last_report_at >= #{freshAfter}
      and s.last_lat is not null and s.last_lng is not null
      and m.del_flag = 0
      and (6371000 * acos(least(1,
            cos(radians(#{lat})) * cos(radians(s.last_lat))
            * cos(radians(s.last_lng) - radians(#{lng}))
            + sin(radians(#{lat})) * sin(radians(s.last_lat))
          ))) <= #{radiusM}
) t
where t.rn = 1
order by t.elapsedSec desc
limit #{limit}

mapper.update:
update roam_session set finish_result_json = #{resultJson}
where id = #{sessionId} and member_id = #{memberId} and status = 1
  and finish_result_json is null

mapper.select:
select f.id, f.geohash7, unix_timestamp(s.finished_at)*1000 as locationExpiresFrom from roam_fog_tile f join roam_session s on s.id = f.session_id and s.member_id = f.member_id
where f.member_id = #{memberId} and f.id > #{afterId}
  and (s.status = 0 or (s.status = 1 and s.finished_at > date_sub(now(), interval 30 day)))
order by f.id asc
limit #{limit}

select sourceId, avatar from (
    select v.source_id as sourceId, m.avatar as avatar,
           row_number() over (partition by v.source_id order by v.visitedAt desc, v.maxId desc) as rn
    from (
        select f.source_id, f.member_id, max(f.visited_at) as visitedAt, max(f.id) as maxId
        from roam_shop_visit f join roam_session s on s.id=f.session_id and s.member_id=f.member_id
        where f.source_type = #{sourceType}
          and (s.status=0 or (s.status=1 and s.finished_at > date_sub(now(),interval 30 day)))
          and f.source_id in
          #{sid}
        group by f.source_id, f.member_id
    ) v join ums_member m on m.id = v.member_id
    where m.del_flag = 0 and m.avatar is not null and m.avatar <> ''

      and coalesce((
          select c.event_type from consent_record c
          where c.member_id = v.member_id and c.doc_type = 'privacy_policy'
            and c.scene = 'roam_location' and c.scope_type is null and c.scope_id is null
          order by c.id desc limit 1
      ), 'AGREE') <> 'REVOKE'
) t where t.rn <= #{limit}

select distinct source_id as sourceId,member_id as memberId from roam_shop_visit
where source_type=#{sourceType} and member_id > 0
and source_id in #{id}

select visitor_fingerprint from roam_shop_visitor_claim where source_type=#{sourceType}
and source_id in #{id}
and visitor_fingerprint in #{fp}

select p.gallery_json, p.photo_required, p.badge_code, t.photo_require_desc, p.id as poi_id, p.name as name, p.description as description, p.lat as lat, p.lng as lng, p.radius_m as radius_m, p.node_level as node_level, p.tags as tags, p.cover_img as cover_img, p.city_code as city_code, p.status as status, p.merchant_id as merchant_id, m.name as merchant_name, m.logo as merchant_logo, coalesce(m.address,p.address) as merchant_address, m.phone as merchant_phone, p.template_id as template_id, t.title as template_title, t.interaction_type as interaction_type, t.validation_method as validation_method, t.coupon_id as coupon_id, t.question_name as question_name, t.question_a as question_a, t.question_b as question_b, t.question_c as question_c, t.question_d as question_d, (6371000 * acos(least(1, cos(radians(#{originLat})) * cos(radians(p.lat)) * cos(radians(p.lng) - radians(#{originLng})) + sin(radians(#{originLat})) * sin(radians(p.lat)) ))) as distance from roam_poi p left join mms_merchant m on p.merchant_id = m.id left join cms_member_template t on p.template_id = t.id where p.type = 2 and p.status = 1 and and p.lat between #{minLat} and #{maxLat} and p.lng between #{minLng} and #{maxLng}
and (p.name like concat('%', #{keyword}, '%') or m.name like concat('%', #{keyword}, '%'))
and m.category_id = #{categoryId} and p.tags like concat('%', #{tag}, '%') and m.city_role like concat('%', #{cityRole}, '%') order by distance asc, p.node_level desc, p.sort asc, p.id desc

select poi_id from roam_poi_reward_log where member_id = #{memberId} and status = 1
and poi_id in #{id}
and 1 = 0

select count(*) from roam_poi
where application_type = 1 and applicant_merchant_id = #{applicantMerchantId}
  and audit_status in (0, 3) and merchant_id is null

mapper.update:
update roam_poi set audit_status = 2, audit_reason = #{reason}
where id = #{id} and application_type in (1, 2) and audit_status = 0
  and applicant_merchant_id is not null and merchant_id is null

update roam_poi set status = #{status}
where id = #{id}
  and (#{status} = 0 or audit_status is null or audit_status = 1)

mapper.select:
select id,member_id,poi_id,claim_fingerprint from roam_poi_reward_log where (create_time is null or create_time <= #{cutoff})
  and (trigger_lat is not null or trigger_lng is not null or (coalesce(coupon_id,0)=0 and poi_id is not null))
order by id limit #{limit}
